#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json, datetime
import xml.etree.ElementTree as ET
from fractions import Fraction
from decimal import Decimal

FACT = {'kg': Fraction(1), 'g': Fraction(1, 1000), 'lb': Fraction(45359237, 10**8),
        'oz': Fraction(28349523125, 10**12)}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
EPOCH = datetime.date(1899, 12, 30)
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}
DEBUG = os.environ.get('SUMMARIZE_DEBUG')


def warn(*a):
    if DEBUG:
        print('WARN', *a, file=sys.stderr)


def read_bytes(path):
    b = open(path, 'rb').read()
    while b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', 'replace')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le', 'replace')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be', 'replace')
    enc = 'utf-8'
    head = b[:4096].decode('latin-1')
    for line in head.split('\n')[:10]:
        m = re.match(r'\s*#\s*charset\s*:\s*([\w.\-]+)', line, re.I)
        if m:
            enc = m.group(1)
            break
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode('latin-1')


def norm_id(s):
    m = re.search(r'(\d+)', s)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def counted(s):
    return s in ('delivered', 'delivered_late')


def parse_num(s, decimal_comma=False):
    s = s.strip()
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    s = s.replace(' ', '')
    return Fraction(Decimal(s))


def split_weight(s, decimal_comma=False):
    """value possibly with trailing unit -> (Fraction, unit or None)"""
    m = re.match(r'^\s*([-+]?[\d.,\s]*\d|[-+]?\.\d+)\s*([A-Za-z]*)\s*$', s)
    if not m:
        raise ValueError('bad weight %r' % s)
    u = m.group(2).lower() or None
    if u and u not in FACT:
        raise ValueError('bad unit %r' % s)
    return parse_num(m.group(1), decimal_comma), u


def parse_date(s, form):
    """returns (date, datetime-utc or None)"""
    s = s.strip()
    if re.search(r'\d[T ]\d{1,2}:\d{2}', s):
        t = s.replace(' ', 'T', 1) if 'T' not in s else s
        if t.endswith('Z') or t.endswith('z'):
            t = t[:-1] + '+00:00'
        dt = datetime.datetime.fromisoformat(t)
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc)
        return dt.date()
    f = (form or 'iso').strip()
    fl = f.lower()
    if fl == 'serial' or re.fullmatch(r'\d{5,6}(\.\d+)?', s) and fl == 'serial':
        return EPOCH + datetime.timedelta(days=int(float(s)))
    if fl in ('iso', 'ymd', 'yyyy-mm-dd'):
        y, m, d = re.split(r'[-/.]', s)
        return datetime.date(int(y), int(m), int(d))
    if fl in ('dmy', 'dd-mm-yyyy', 'dd/mm/yyyy', 'dd.mm.yyyy'):
        d, m, y = re.split(r'[-/.]', s)
        return datetime.date(int(y), int(m), int(d))
    if fl in ('mm/dd/yyyy', 'mdy'):
        m, d, y = re.split(r'[-/.]', s)
        return datetime.date(int(y), int(m), int(d))
    if fl == 'yyyyddd':
        return datetime.date(int(s[:4]), 1, 1) + datetime.timedelta(days=int(s[4:7]) - 1)
    if fl == 'yyyymmdd':
        return datetime.date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    # fallback auto
    m = re.fullmatch(r'(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})', s)
    if m:
        return datetime.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    raise ValueError('bad date %r form %r' % (s, form))


# record: dict(id, type in new/corr/void, date, kg(Fraction), status)

def rec(i, typ, date=None, kg=None, status=None):
    return dict(id=norm_id(i), type=typ, date=date, kg=kg, status=status)


# ---------- delimited ----------

def logical_rows(text):
    """yield ('comment', line) or ('row', raw_text) honoring quoted multi-line fields."""
    lines = text.split('\n')
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i].rstrip('\r')
        i += 1
        if line.strip() == '':
            continue
        if line.startswith('#'):
            yield 'comment', line
            continue
        raw = line
        while raw.count('"') % 2 == 1 and i < n:
            raw += '\n' + lines[i].rstrip('\r')
            i += 1
        yield 'row', raw


def parse_directive(line):
    m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*?)\s*$', line)
    if m:
        return m.group(1).strip().lower(), m.group(2)
    return None, None


def split_row(raw, delim):
    if delim == ',':
        return next(csv.reader([raw], delimiter=',', quotechar='"'))
    return raw.split(delim)


def unit_from_name(name):
    m = re.search(r'(?:^|[_\-\s])(kg|g|lb|oz)$', name.lower())
    return m.group(1) if m else None


def parse_delimited(depot, text, delim, cols, idcol, typecol, typemap, weightcol,
                    datecol, statuscol, base_date, base_unit, decimal_comma=False,
                    statusmap=None, ignore_prefix=()):
    seq = None
    directives = {}
    header = None
    out = []
    for kind, raw in logical_rows(text):
        if kind == 'comment':
            k, v = parse_directive(raw)
            if k is not None:
                if k == 'seq' and seq is None:
                    try:
                        seq = int(v)
                    except ValueError:
                        pass
                directives[k] = v
            else:
                m = re.search(r'seq=(\d+)', raw)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        fields = split_row(raw, delim)
        names = [f.strip().lower() for f in fields]
        if all(n in cols or unit_from_name(n) and re.sub(r'[_\-\s]*(kg|g|lb|oz)$', '', n) in cols
               for n in names) and idcol in names:
            header = names
            continue
        if header is None:
            warn('no header', depot, raw[:60])
            continue
        first = fields[0].strip().upper()
        if first == 'TOTAL' or first.startswith('TOTAL') and len(fields) < len(header) - 1:
            continue
        rowunit = None
        if len(fields) == len(header) + 1:
            rowunit = fields[-1].strip().lower()
            fields = fields[:-1]
            if rowunit not in FACT:
                warn('odd extra field', depot, raw[:80])
                rowunit = None
        elif len(fields) != len(header):
            warn('field count', depot, len(fields), len(header), raw[:80])
            if len(fields) < len(header):
                # likely trailer / void rows
                if not any(fields[header.index(idcol)].strip() for _ in [0]) if idcol in header and header.index(idcol) < len(fields) else True:
                    continue
                fields = fields + [''] * (len(header) - len(fields))
            else:
                continue
        row = dict(zip(header, fields))
        rid = row.get(idcol, '').strip()
        if not re.search(r'\d', rid):
            continue
        t = typemap.get(row.get(typecol, '').strip().upper() if typecol else '', None)
        if t is None:
            warn('type', depot, raw[:80])
            t = 'new'
        if t == 'void':
            out.append(rec(rid, 'void'))
            continue
        # weight
        wname = None
        for n in header:
            if n == weightcol or re.sub(r'[_\-\s]*(kg|g|lb|oz)$', '', n) == weightcol and unit_from_name(n):
                wname = n
                break
        val, vunit = split_weight(row[wname], decimal_comma)
        unit = vunit or unit_from_name(wname) or rowunit or \
            (directives.get('unit') or directives.get('weight unit') or '').split()[0:1] and None
        if not unit:
            d = directives.get('unit') or directives.get('weight unit')
            if d:
                unit = d.split()[0].lower()
            else:
                unit = base_unit
        dform = directives.get('dates') or directives.get('date format') or base_date
        date = parse_date(row[datecol], dform)
        st = row.get(statuscol, '')
        st = statusmap[st.strip().upper()] if statusmap else norm_status(st)
        out.append(rec(rid, t, date, val * FACT[unit], st))
    return seq, out


def p_east(text):
    return parse_delimited('east', text, ',', {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
                           'id', 'type', {'N': 'new', 'C': 'corr', 'V': 'void'}, 'gross', 'shipped', 'status',
                           'YMD', 'kg')


def p_lakeside(text):
    return parse_delimited('lakeside', text, ',', {'id', 'kind', 'booked', 'shipped', 'gross', 'net', 'status'},
                           'id', 'kind', {'': 'new', 'CORR': 'corr', 'VOID': 'void'}, 'gross', 'shipped', 'status',
                           'iso', 'kg')


def p_river(text):
    return parse_delimited('river', text, '\t', {'t', 'ref', 'shipped', 'weight', 'status'},
                           'ref', 't', {'': 'new', 'C': 'corr', 'V': 'void'}, 'weight', 'shipped', 'status',
                           'MM/DD/YYYY', 'kg')


def p_west(text):
    return parse_delimited('west', text, ';', {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
                           'id', 'typ', {'N': 'new', 'C': 'corr', 'V': 'void'}, 'weight', 'shipped', 'status',
                           'DD.MM.YYYY', 'kg', decimal_comma=True)


def p_harbor(text):
    return parse_delimited('harbor', text, '|', {'rec', 'ref', 'date', 'weight', 'state'},
                           'ref', 'rec', {'NEW': 'new', 'COR': 'corr', 'VOID': 'void'}, 'weight', 'date', 'state',
                           'iso', 'kg',
                           statusmap={'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
                                      'RET': 'returned', 'HLD': 'held'})


# ---------- north ----------

def p_north(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            warn('bad json', line[:60])
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            k = (o.get('kind') or 'new').lower()
            t = {'new': 'new', 'amend': 'corr', 'void': 'void'}.get(k)
            if t is None:
                warn('kind', k)
                t = 'new'
            if t == 'void':
                out.append(rec(o['id'], 'void'))
                continue
            kg = None
            for key, val in o.items():
                m = re.fullmatch(r'weight_(kg|g|lb|oz)', key.lower())
                if m:
                    kg = Fraction(Decimal(str(val))) * FACT[m.group(1)]
            date = parse_date(o['shipped_at'], 'iso')
            out.append(rec(o['id'], t, date, kg, norm_status(o.get('status'))))
    return seq, out


# ---------- central ----------

def p_central(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').lower()
    out = []
    for sh in root.iter('shipment'):
        def get(name):
            if sh.get(name) is not None:
                return sh.get(name)
            c = sh.find(name)
            return c.text if c is not None and c.text else None
        t = {'correction': 'corr', 'void': 'void'}.get((sh.get('type') or 'new').lower(), 'new')
        if t == 'void':
            out.append(rec(sh.get('id'), 'void'))
            continue
        w = sh.find('weight')
        wt = (w.text or '').strip() if w is not None else get('weight')
        val, vu = split_weight(wt)
        unit = vu or (w.get('unit') if w is not None else None) or sh.get('weight-unit') or runit
        out.append(rec(sh.get('id'), t, parse_date(get('shipped'), 'iso'), val * FACT[unit.lower()],
                       norm_status(get('status'))))
    return seq, out


# ---------- south ----------
LAYOUTS = {
    'FW1': dict(len=42, id=(1, 9), type=(10, 10), date=(11, 17), w=(18, 25), st=(26, 26), df='yyyyddd', wu=Fraction(1, 1000)),
    'FW2': dict(len=43, id=(2, 10), type=(1, 1), date=(11, 18), w=(19, 26), st=(27, 27), df='yyyymmdd', wu=Fraction(1, 100)),
    'FW3': dict(len=41, id=(1, 9), type=(17, 17), date=(10, 16), w=(18, 24), st=(25, 25), df='yyyyddd',
                wu=Fraction(1, 10) * FACT['lb']),
}
SCODE = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def p_south(text):
    seq = None
    cur = None
    out = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if '\x0c' in line or 'SOUTH DEPOT' in line:
            continue
        if line.strip() == '':
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                cur = m.group(1).upper()
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        lay = None
        for name, L in LAYOUTS.items():
            if len(line) == L['len']:
                lay = name
        if lay is None:
            if cur in LAYOUTS and len(line) < LAYOUTS[cur]['len'] and len(line) >= LAYOUTS[cur]['st'][1]:
                lay = cur
                line = line.ljust(LAYOUTS[cur]['len'])
            else:
                warn('south odd line', repr(line))
                continue
        L = LAYOUTS[lay]
        f = lambda k: line[L[k][0] - 1:L[k][1]]
        t = {'N': 'new', 'C': 'corr', 'V': 'void'}.get(f('type'))
        if t is None:
            warn('south type', repr(line))
            continue
        if t == 'void':
            out.append(rec(f('id'), 'void'))
            continue
        d = parse_date(f('date'), L['df'])
        out.append(rec(f('id'), t, d, int(f('w')) * L['wu'], SCODE.get(f('st').strip().upper(), 'unknown')))
    return seq, out


PARSERS = {'east': p_east, 'lakeside': p_lakeside, 'river': p_river, 'west': p_west, 'harbor': p_harbor,
           'north': p_north, 'south': p_south}


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split('-')[0]
        exports.setdefault(depot, [])
        b = read_bytes(path)
        try:
            if depot == 'central':
                seq, recs = p_central(b)
            elif depot in PARSERS:
                seq, recs = PARSERS[depot](decode(b))
            else:
                warn('unknown depot', depot)
                continue
        except Exception as e:
            warn('FAILED', name, repr(e))
            raise
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        exps.sort(key=lambda e: e[0])
        cur = {}
        for seq, name, recs in exps:
            for r in recs:
                if r['id'] is None:
                    continue
                if r['type'] == 'new':
                    if r['id'] in cur:
                        resends += 1
                    else:
                        cur[r['id']] = r
                elif r['type'] == 'corr':
                    cur[r['id']] = r
                    corrections += 1
                else:
                    cur.pop(r['id'], None)
                    corrections += 1
        current[depot] = cur

    rank = {d: i for i, d in enumerate(ORDER)}
    owners = {}
    for depot in current:
        for i in current[depot]:
            owners.setdefault(i, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Fraction(0)] for d in exports}
    months = {}
    for i, ds in owners.items():
        d = min(ds, key=lambda x: rank.get(x, 99))
        r = current[d][i]
        if not counted(r['status']):
            continue
        depots[d][0] += 1
        depots[d][1] += r['kg']
        mk = '%04d-%02d' % (r['date'].year, r['date'].month)
        m = months.setdefault(mk, [0, Fraction(0)])
        m[0] += 1
        m[1] += r['kg']

    def rnd(fr):
        q = (fr * 100)
        n = q.numerator * 2 + q.denominator
        n = n // (2 * q.denominator)
        return n / 100

    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': rnd(v[1])} for d, v in sorted(depots.items())},
        'months': {k: {'shipments': v[0], 'total_kg': rnd(v[1])} for k, v in sorted(months.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(res, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main()
